/*
 * dir_$old_find_overflow_slot - find (or make) a free slot on a hash chain
 * of an old-format directory
 *
 * Original address: 0x00E54F8A
 * Size: 512 bytes (0x00E54F8A .. 0x00E55189)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol); its one
 * caller is dir_$old_add_entry (0x00E55344), once the inline slots are
 * full.  Also holds its two chain helpers, which have no other caller:
 * dir_$old_chain_push (0x00E54D10, 82 bytes, was FUN_00e54d10) and
 * dir_$old_chain_unlink (0x00E54D62, 106 bytes, was FUN_00e54d62).
 *
 * Frame: (0x8,A6) handle (A2), (0xC,A6) hash word (D4), (0xE,A6) replace
 * flag byte (D2b, the high byte of its word slot), (0x10,A6) block_out,
 * (0x14,A6) slot_out.  A6-0x1C = &hash head - 0x3AA, A6-0xA the replace
 * walk's step count.  Result D5b, 0xFF unless the directory is full.
 *
 * Blocks:
 *   0x00E54F9E-0x00E54FBC  result = TRUE; *block_out = head of the chain
 *   0x00E54FC0-0x00E55042  each block of the chain with a free slot (in-use
 *                          count below the per-block slot count): the first
 *                          slot whose type byte is 0 -> *slot_out = j, clear
 *                          its no-evict bit; in replace mode a block not at
 *                          the head is moved to the head (unlink, push)
 *   0x00E55046-0x00E5504C  next block (D3 remembers the one just left)
 *   0x00E5505A-0x00E55068  chain full: *block_out = dir_$old_alloc_block;
 *                          got one -> 0x00E55130
 *   0x00E5506C-0x00E5506E  not replace mode: FALSE
 *   0x00E55072-0x00E55114  replace mode: from the chain's last block back
 *                          towards the head (+0x36C), at most max-blocks
 *                          (+0x6) steps: the first type-1 slot without the
 *                          no-evict bit is evicted with
 *                          dir_$old_delete_entry(handle, block, j, hash) and
 *                          reused (*slot_out = j, *block_out = block), the
 *                          block moved to the head unless it is already
 *   0x00E55118-0x00E5512E  none: *block_out = dir_$old_reclaim_block(handle,
 *                          hash); 0 -> FALSE
 *   0x00E55130-0x00E5516E  a fresh block: in-use count 0, type 1,
 *                          *slot_out = 1, every slot's type and no-evict
 *                          bit cleared
 *   0x00E55172-0x00E5517C  push it on the chain
 *
 * Quirks reproduced:
 *   - The step counter is compared unsigned after the increment (`bhi'), so
 *     the walk looks at max-blocks + 1 blocks at most.
 *   - dir_$old_delete_entry gets a reserved Pascal result word it never
 *     fills.
 */

#include "dir/dir_internal.h"

/*
 * dir_$old_chain_push (0x00E54D10) - put block at the head of hash chain
 * `hash'.  Frame: (0x8,A6) handle (A0), (0xC,A6) hash (D0), (0xE,A6) block
 * (D1).
 *   0x00E54D26-0x00E54D3E  old = head; old != 0 -> old.prev = block
 *   0x00E54D42-0x00E54D54  head = block; block.prev = 0; block.next = old
 */
static void dir_$old_chain_push(uint32_t handle, uint16_t hash, uint16_t block)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);
    uint16_t old;                                       /* D2 */

    old = DIR_OLD_HASH_HEAD(dir, hash);
    if (old != 0) {
        DIR_OLD_W(DIR_OLD_BLOCK(dir, old), DIR_OLD_BLOCK_PREV) = block;
    }
    DIR_OLD_HASH_HEAD(dir, hash) = block;
    DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_PREV) = 0;
    DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_NEXT) = old;
}

/*
 * dir_$old_chain_unlink (0x00E54D62) - take block out of hash chain
 * `hash'.  Frame: (0x8,A6) handle (A0), (0xC,A6) hash (D0), (0xE,A6) block
 * (D1).
 *   0x00E54D76-0x00E54D8C  next = block.next, prev = block.prev; when they
 *                          are equal next is taken as 0
 *   0x00E54D8E-0x00E54D9C  next != 0 -> next.prev = prev
 *   0x00E54DA0-0x00E54DBE  prev != 0 -> prev.next = next, else head = next
 * Quirk: the equal test also fires when both links are 0 (harmless) and
 * when a two-element cycle would link a block to itself.
 */
static void dir_$old_chain_unlink(uint32_t handle, uint16_t hash,
                                  uint16_t block)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);
    uint16_t next;                                      /* D2 */
    uint16_t prev;                                      /* D1 */

    next = DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_NEXT);
    prev = DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_PREV);
    if (prev == next) {
        next = 0;
    }
    if (next != 0) {
        DIR_OLD_W(DIR_OLD_BLOCK(dir, next), DIR_OLD_BLOCK_PREV) = prev;
    }
    if (prev != 0) {
        DIR_OLD_W(DIR_OLD_BLOCK(dir, prev), DIR_OLD_BLOCK_NEXT) = next;
    } else {
        DIR_OLD_HASH_HEAD(dir, hash) = next;
    }
}

int8_t dir_$old_find_overflow_slot(uint32_t handle, uint16_t hash,
                                    int8_t flags, uint16_t *bucket_out,
                                    uint16_t *sub_slot_out)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);  /* A2 */
    uint8_t *block;                                    /* A0 */
    dir_$old_slot_t *slot;
    uint16_t slots;                                    /* (0x8,A2) */
    uint16_t last;                                     /* D3 */
    uint16_t steps;                                    /* A6-0xA */
    uint16_t j;                                        /* D1 / D2 */
    int16_t m;                                         /* D0 / D1 */

    /* 0x00E54F9E-0x00E54FBC */
    *bucket_out = DIR_OLD_HASH_HEAD(dir, hash);
    last = *bucket_out;

    while (*bucket_out != 0) {
        /* 0x00E54FC0-0x00E54FDC */
        block = DIR_OLD_BLOCK(dir, *bucket_out);
        slots = DIR_OLD_W(dir, DIR_OLD_HDR_BLOCK_SLOTS);
        if (block[DIR_OLD_BLOCK_USED] < slots && slots != 0) {
            /* 0x00E54FDE-0x00E55042 */
            m = (int16_t)(slots - 1);
            j = 1;
            do {                                        /* dbf D0w */
                slot = DIR_OLD_BLOCK_SLOT(dir, *bucket_out, j);
                if (slot->type == 0) {
                    /* 0x00E54FF6-0x00E5500A */
                    *sub_slot_out = j;
                    slot = DIR_OLD_BLOCK_SLOT(dir, *bucket_out, *sub_slot_out);
                    ((uint8_t *)slot)[DIR_OLD_SLOT_FLAGS] &=
                        (uint8_t)~DIR_OLD_SLOT_NO_EVICT;
                    /* 0x00E55010-0x00E55036 */
                    if (flags < 0) {
                        last = *bucket_out;
                        if (last != DIR_OLD_HASH_HEAD(dir, hash)) {
                            dir_$old_chain_unlink(handle, hash, last);
                            dir_$old_chain_push(handle, hash, last);
                        }
                    }
                    return (int8_t)0xFF;
                }
                j++;
            } while (m-- != 0);
        }

        /* 0x00E55046-0x00E5504C */
        last = *bucket_out;
        *bucket_out = DIR_OLD_W(block, DIR_OLD_BLOCK_NEXT);
    }

    /* 0x00E5505A-0x00E55068 */
    *bucket_out = dir_$old_alloc_block(handle);
    if (*bucket_out == 0) {
        /* 0x00E5506C-0x00E5506E */
        if (flags >= 0) {
            return 0;
        }

        /* 0x00E55072-0x00E55114 */
        steps = 0;
        while (last != 0) {
            slots = DIR_OLD_W(dir, DIR_OLD_HDR_BLOCK_SLOTS);
            if (slots != 0) {
                m = (int16_t)(slots - 1);
                j = 1;
                do {                                    /* dbf D1w */
                    slot = DIR_OLD_BLOCK_SLOT(dir, last, j);
                    if (slot->type == DIR_OLD_SLOT_IN_USE &&
                        (((uint8_t *)slot)[DIR_OLD_SLOT_FLAGS] & DIR_OLD_SLOT_NO_EVICT) == 0) {
                        /* 0x00E550AE-0x00E550E6 */
                        dir_$old_delete_entry(handle, last, j, hash);
                        *sub_slot_out = j;
                        *bucket_out = last;
                        if (DIR_OLD_HASH_HEAD(dir, hash) != *bucket_out) {
                            dir_$old_chain_unlink(handle, hash, *bucket_out);
                            dir_$old_chain_push(handle, hash, *bucket_out);
                        }
                        return (int8_t)0xFF;
                    }
                    j++;
                } while (m-- != 0);
            }
            /* 0x00E550F6-0x00E55110 */
            last = DIR_OLD_W(DIR_OLD_BLOCK(dir, last), DIR_OLD_BLOCK_PREV);
            steps++;
            if (steps > DIR_OLD_W(dir, DIR_OLD_HDR_MAX_BLOCKS)) {
                break;
            }
        }

        /* 0x00E55118-0x00E5512E */
        *bucket_out = dir_$old_reclaim_block(handle, hash);
        if (*bucket_out == 0) {
            return 0;
        }
    }

    /* 0x00E55130-0x00E5516E */
    block = DIR_OLD_BLOCK(dir, *bucket_out);
    block[DIR_OLD_BLOCK_USED] = 0;
    block[DIR_OLD_BLOCK_TYPE] = DIR_OLD_SLOT_IN_USE;
    *sub_slot_out = 1;
    slots = DIR_OLD_W(dir, DIR_OLD_HDR_BLOCK_SLOTS);
    if (slots != 0) {
        m = (int16_t)(slots - 1);
        j = 1;
        do {                                            /* dbf D1w */
            slot = DIR_OLD_BLOCK_SLOT(dir, *bucket_out, j);
            slot->type = 0;
            ((uint8_t *)slot)[DIR_OLD_SLOT_FLAGS] &=
                (uint8_t)~DIR_OLD_SLOT_NO_EVICT;
            j++;
        } while (m-- != 0);
    }

    /* 0x00E55172-0x00E5517C */
    dir_$old_chain_push(handle, hash, *bucket_out);
    return (int8_t)0xFF;
}
